function reviewedMigrationRepairInput(file,text){
 const row=migrationRepairSourceRecords.find(r=>r.path===file);if(!row)return text;
 const hash=value=>createHash('sha256').update(value).digest('hex'),pin=hash(text);
 if(pin===row.parentSha256)return text;
 assert.equal(pin,row.candidateSha256,'unreviewed current migration repair input '+file);
 for(const h of [...row.hunks].reverse()){
  assert.equal(text.slice(h.start,h.start+h.after.length),h.after);
  text=text.slice(0,h.start)+h.before+text.slice(h.start+h.after.length);
 }
 assert.equal(hash(text),row.parentSha256);return text;
}

const ts=createRequire(new URL('../services/pg-api/package.json',import.meta.url))('typescript')
const read=file=>reviewedMigrationRepairInput(file,fs.readFileSync(new URL('../'+file,import.meta.url),'utf8'))
function ast(file,source=read(file)){const result=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true,file.endsWith('.tsx')?ts.ScriptKind.TSX:ts.ScriptKind.JS);assert.equal(result.parseDiagnostics.length,0);return result}
function nodes(root,predicate){const list=[];function visit(n){if(predicate(n))list.push(n);ts.forEachChild(n,visit)}visit(root);return list}
function initializer(root,name){const found=nodes(root,n=>ts.isVariableDeclaration(n)&&ts.isIdentifier(n.name)&&n.name.text===name);assert.equal(found.length,1,name);return found[0].initializer}
const storyText=read('tests/pg-original-plugin-market-genuine.spec.mjs'),story=ast('tests/pg-original-plugin-market-genuine.spec.mjs',storyText),loginText=initializer(story,'login').getText(story),advancedText=initializer(story,'advanced').getText(story)
function jsxText(n){if(ts.isJsxText(n))return n.text;if(ts.isJsxElement(n))return n.children.map(jsxText).join('');if(ts.isJsxSelfClosingElement(n))return '';throw Error('dynamic_source_title_requires_review')}
function hasAncestor(node,tag){for(let at=node.parent;at;at=at.parent)if(ts.isJsxElement(at)&&at.openingElement.tagName.getText()==tag)return true;return false}
const h1Pattern=nodes(initializer(story,'login'),n=>ts.isRegularExpressionLiteral(n));assert.equal(h1Pattern.length,1);const h1Regex=new RegExp(h1Pattern[0].text.slice(1,-1))
const summaryPattern=nodes(initializer(story,'advanced'),n=>ts.isRegularExpressionLiteral(n));assert.equal(summaryPattern.length,1);const summaryRegex=new RegExp(summaryPattern[0].text.slice(1,-1))
