function pageData(who='alice',title='插件市场',opened=false){const events=[],state={authenticated:true,who,url:'',open:opened,clicks:0,title};const p={events,state,async goto(url){state.url=url;events.push('goto')},getByLabel(name,options){assert.equal(name,'密码');assert.equal(options.exact,true);return{async fill(value){assert.equal(value,f.credentials[who].password);events.push('password')}}},getByRole(role,options){if(role==='textbox'){assert.equal(options.name,'工作邮箱');return{async fill(value){assert.equal(value,f.credentials[who].email);events.push('email')}}}if(role==='button'){assert.equal(options.name,'登录');return{async click(){events.push('login-click');state.url=f.url}}}assert.equal(role,'heading');assert.equal(options.exact,true);assert(['探索插件','工具市场'].includes(options.name));return{kind:options.name,visible:()=>options.name==='探索插件'||state.open}},locator(selector){if(selector==='main[data-studio-fluid-page="plugins"] h1'){events.push('actual-h1');return{kind:'h1',text:state.title,count:1,visible:()=>true}}assert.equal(selector,'summary');return{filter(options){assert(options.hasText.test('高级功能 · MCP 公共注册表、工具试调与调用日志 面向企业自建或需要手动管理的 MCP'));return{kind:'summary',count:1,visible:()=>true,async click(){state.clicks++;state.open=true;events.push('summary-click')},locator(parent){assert.equal(parent,'xpath=parent::details');return{kind:'details',async getAttribute(name){assert.equal(name,'open');return state.open?'':null},attr:()=>state.open?'':null}}}}}}};return p}
function check(value){return{toBe(expected){assert.equal(value,expected)},async toHaveURL(expected){assert.equal(value.state.url,expected);value.events.push('url-confirmed')},async toHaveCount(expected){assert.equal(value.count,expected)},async toHaveText(pattern){assert(pattern.test(value.text))},async toBeVisible(){assert.equal(value.visible(),true)},async toHaveAttribute(name,expected){assert.equal(name,'open');assert.equal(value.attr(),expected)}}}
function helpers(globalPage,authenticated=true,ownerOverride){const ports={page:globalPage,f,expect:check,wire(p,route,method){assert.equal(route,'/api/native-auth/login');assert.equal(method,'POST');p.events.push('wire-before-click');return Promise.resolve({authenticated,user:{id:ownerOverride??f.users[p.state.who]}})}};vm.runInNewContext('globalThis.login='+loginText+';globalThis.advanced='+advancedText,ports,{timeout:1000});return ports}

