for(const title of ['插件','市场','其他插件市场','插件市场管理','插件市场\n其他内容'])test('partial or extra h1 text stays a failure '+JSON.stringify(title),async()=>{assert.equal(h1Regex.test(title),false);const p=pageData('alice',title);await assert.rejects(helpers(p).login('alice',p))})
